mapper.select:
SELECT p.id, p.station_id AS stationId, s.name AS stationName, p.space_id AS spaceId, ps.location AS spaceName, p.car_no AS carNo, p.in_time AS inTime, p.over_time AS overTime, p.status, p.remark, p.reserve1, p.reserve2, p.creator, p.updater, p.create_time AS createTime, p.update_time AS updateTime FROM in_park_status p LEFT JOIN station_info s ON p.station_id = s.id AND s.deleted = 0 LEFT JOIN parking_space_info ps ON p.space_id = ps.id AND ps.deleted = 0 WHERE p.deleted = 0
AND p.car_no LIKE CONCAT('%', #{reqVO.carNo}, '%')
AND p.space_id = #{reqVO.spaceId}
AND p.in_time BETWEEN #{reqVO.inTime[0]} AND #{reqVO.inTime[1]}
AND p.status = #{reqVO.status}
AND p.station_id = #{reqVO.stationId}
ORDER BY p.id DESC
